package sem

// E1xx: name binding, that is names, packages, imports and visibility.
var (
	cUnresolvedName        = defineCode("E100", "unresolved-name", "undefined name `{name}`")
	cUnresolvedConstructor = defineCode("E101", "unresolved-constructor", "undefined constructor `{name}`")
	cUnresolvedPackage     = defineCode("E102", "unresolved-package", "package `{path}` not found")
	cUnresolvedMember      = defineCode("E103", "unresolved-member", "package `{path}` has no visible `{name}`")
	cNameRedeclared        = defineCode("E104", "name-redeclared", "`{name}` is already declared in package `{pkg}`")
	cImportConflict        = defineCode("E105", "import-conflict", "`{name}` is already bound in this file")
	cImportPreludeName     = defineCode("E106", "import-prelude-name", "`{name}` is a prelude name and cannot be imported")
	cImportPreludeExplicit = defineCode("E107", "import-prelude-explicit", "`std/prelude` is imported implicitly")
	cImportSelf            = defineCode("E108", "import-self", "`{path}` is the current package; remove the import")
	cImportEntryPackage    = defineCode("E109", "import-entry-package", "`{path}` has top-level statements and cannot be imported")
	cReexportWidens        = defineCode("E110", "reexport-widens", "re-export of `{name}` widens its visibility ({vis} to {vis2})")
	cReexportConflict      = defineCode("E111", "reexport-conflict", "re-exported `{name}` collides with a declaration of this package")
	cReexportCycle         = defineCode("E112", "reexport-cycle", "re-export cycle: {chain}")
	cModuleCycle           = defineCode("E113", "module-cycle", "import cycle between modules: {chain}")
	cPkgDuplicatePath      = defineCode("E114", "pkg-duplicate-path", "package `{path}` is defined by two modules")
	cNotVisible            = defineCode("E115", "not-visible", "`{name}` is not visible here ({vis} of package `{pkg}`)")
	cVisSuperAtRoot        = defineCode("E116", "vis-super-at-root", "`pub(super)` has no parent package at the module root")
	cVisInRemoved          = defineCode("E133", "vis-in-removed", "`pub(in ...)` was removed in v2.8; use `pub(super)` or `pub(module)`")
	cSignaturePrivateType  = defineCode("E118", "signature-private-type", "`{type}` is {vis} but appears in the {vis2} signature of `{name}`")
	cOverloadVisibility    = defineCode("E119", "overload-visibility", "all overloads of `{name}` must share one visibility")
	cImplWitnessVisibility = defineCode("E120", "impl-witness-visibility", "`{type}` asserts `{iface}` with {vis} visibility but witness `{m}` is {vis2}")
	cPredeclaredRedeclared = defineCode("E121", "predeclared-redeclared", "`{name}` is predeclared and cannot be redeclared")
	cNilName               = defineCode("E122", "nil-name", "`nil` cannot be used as a name (v2.6 B3)")
	cTypeAsValue           = defineCode("E123", "type-as-value", "`{name}` is a type, not a value")
	cPackageAsValue        = defineCode("E124", "package-as-value", "`{name}` is a package qualifier; write `{name}.member`")
	cConstraintAsType      = defineCode("E125", "constraint-as-type", "`{name}` is a constraint, not a type")
	cNotAType              = defineCode("E126", "not-a-type", "`{name}` is {what}, not a type")
	cUnderscoreValue       = defineCode("E127", "underscore-value", "`_` is only a pattern or an assignment target")
	cVariantBareForeign    = defineCode("E128", "variant-bare-foreign", "`{name}` is a variant of `{type}` from another package; write `{type}.{name}`")
	cVariantAmbiguous      = defineCode("E129", "variant-ambiguous", "`{name}` is a variant of both `{a}` and `{b}`; qualify it")
	cLangItemMissing       = defineCode("E130", "lang-item-missing", "`{item}` needs package `{pkg}`, which is not loaded")
	cSelfOutsideMember     = defineCode("E131", "self-outside-member", "`self` is only allowed in member functions")
	cSelfOutsideInterface  = defineCode("E132", "self-outside-interface", "`Self` is only available inside an interface body")
)
